﻿import React from 'react';
import {AbsoluteFill, interpolateColors} from 'remotion';
import {useS, T, en, DUR, interpolate, clamp, Easing, FONT, Textura, Profundidad, Brillo, Paso, tono, Camara, Chip, Contador, Ondas, Destello, golpe, h} from './kit';

export const SUBS = {arriba: 230, acento: '#FFC83D'};

const A = [0, 7, 28, 44, 66, 91, 106, 123, 144].map(T);
const GOLD = '#FFC83D', RED = '#FF4D4D', GREEN = '#3DDC84', INK = '#1a2340';
const eo = Easing.out(Easing.cubic), ei = Easing.inOut(Easing.cubic), lineal = (x: number) => x;
const q = (s: number, a: number, b: number, e: (x: number) => number = ei) => interpolate(s, [a, b], [0, 1], {...clamp, easing: e});
const mix = (k: number, a: string, b: string) => interpolateColors(Math.max(0, Math.min(1, k)), [0, 1], [a, b]);
const P = (t: number, x: number, y: number, zoom: number) => ({t, x, y, zoom});

type D = {n: string; p: number};
const HOT: D[] = [{n: 'PLAYA', p: 89}, {n: 'CENTRO', p: 132}, {n: 'TORRE', p: 215}, {n: 'VISTA', p: 260}, {n: 'MAR', p: 275}, {n: 'SUITE', p: 340}];
const H4: D[] = [HOT[0], HOT[1], HOT[2], HOT[5]];

/* ---------- piezas base ---------- */
const Card: React.FC<{x: number; y: number; w: number; hh: number; n: string; p: number; g?: number; rot?: number; sc?: number; op?: number; ring?: number}> = ({x, y, w, hh, n, p, g = 0, rot = 0, sc = 1, op = 1, ring = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`} opacity={op}>
    {ring > 0 && <rect x={-w / 2 - 12} y={-hh / 2 - 12} width={w + 24} height={hh + 24} rx={hh * 0.25} fill="none" stroke={GREEN} strokeWidth={9} opacity={ring} />}
    <rect x={-w / 2} y={-hh / 2 + 8} width={w} height={hh} rx={hh * 0.18} fill="rgba(0,0,0,.28)" />
    <rect x={-w / 2} y={-hh / 2} width={w} height={hh} rx={hh * 0.18} fill={mix(g, '#eaf1ff', GOLD)} stroke={mix(g, '#9fb4e8', '#fff3b0')} strokeWidth={4} />
    <rect x={-w / 2 + hh * 0.1} y={-hh / 2 + hh * 0.12} width={hh * 0.76} height={hh * 0.76} rx={hh * 0.12} fill={mix(g, '#6f8fd6', '#b9780f')} />
    <rect x={-w / 2 + hh * 0.2} y={-hh * 0.28} width={hh * 0.28} height={hh * 0.58} fill="#fff" opacity={0.9} />
    <rect x={-w / 2 + hh * 0.52} y={-hh * 0.08} width={hh * 0.22} height={hh * 0.38} fill="#fff" opacity={0.7} />
    <text x={-w / 2 + hh * 1.0} y={-hh * 0.02} fontSize={hh * 0.3} fontWeight={800} fill={INK}>{n}</text>
    <text x={-w / 2 + hh * 1.0} y={hh * 0.3} fontSize={hh * 0.22} fontWeight={800} fill={mix(g, '#4c6fd0', '#8a5a00')}>★★★★</text>
    <text x={w / 2 - hh * 0.18} y={hh * 0.14} textAnchor="end" fontSize={hh * 0.42} fontWeight={800} fill={INK}>{'$' + p}</text>
  </g>
);

const Lista: React.FC<{s: number; cx: number; y0: number; dy: number; w: number; hh: number; data: D[]; ords: number[][]; ts: number[]; oro?: number; dd?: number; ap?: number; salto?: number; solo?: number; dim?: number; ring?: number}> = ({
  s, cx, y0, dy, w, hh, data, ords, ts, oro = 0, dd = 0.6, ap = -1, salto = 0, solo = -1, dim = 0, ring = 0,
}) => {
  const items = data
    .map((_, c) => {
      let k = ords[0].indexOf(c), lift = 0;
      for (let j = 1; j < ords.length; j++) {
        if (s < ts[j]) break;
        const e = q(s, ts[j], ts[j] + dd);
        const a = ords[j - 1].indexOf(c), b = ords[j].indexOf(c);
        k = a + (b - a) * e;
        lift = a === b ? 0 : Math.sin(e * Math.PI);
      }
      return {c, k, lift};
    })
    .sort((a, b) => a.lift - b.lift);
  return (
    <>
      {items.map(({c, k, lift}) => {
        const d = data[c];
        const sg = c % 2 ? 1 : -1;
        const a = ap < 0 ? 1 : q(s, ap + c * 0.09, ap + c * 0.09 + 0.4, eo);
        const bob = Math.sin(s * 2.2 + c * 1.3) * 3;
        const op = a * (1 - dim * (c === solo ? 0 : 0.65));
        return <Card key={c} x={cx + lift * sg * 26} y={y0 + k * dy - lift * salto + bob + (1 - a) * 70} w={w} hh={hh} n={d.n} p={d.p} g={d.p >= 200 ? oro : 0} rot={lift * sg * 5} sc={a * (1 + lift * 0.07)} op={op} ring={c === solo ? ring : 0} />;
      })}
    </>
  );
};

const Fruta: React.FC<{x: number; y: number}> = ({x, y}) => (
  <g transform={`translate(${x} ${y})`}>
    <circle r={15} cy={3} fill="#8b99b8" />
    <ellipse cx={5} cy={-14} rx={9} ry={4} transform="rotate(-35 5 -14)" fill="#8b99b8" />
    <circle cx={15} cy={0} r={6} fill="#c9d2e6" />
  </g>
);

const Laptop: React.FC<{id: string; x: number; y: number; k?: number; mac?: boolean; rot?: number; children?: React.ReactNode}> = ({id, x, y, k = 1, mac = false, rot = 0, children}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
    <defs><clipPath id={id}><rect x={-222} y={-472} width={444} height={452} rx={10} /></clipPath></defs>
    <rect x={-240} y={-490} width={480} height={490} rx={26} fill="#1b2748" stroke="#8fa6d8" strokeWidth={6} />
    <rect x={-222} y={-472} width={444} height={452} rx={10} fill="#f1f5ff" />
    <g clipPath={`url(#${id})`}>
      <rect x={-222} y={-472} width={444} height={36} fill="#cdd8f2" />
      <circle cx={-198} cy={-454} r={7} fill="#ff6b6b" /><circle cx={-176} cy={-454} r={7} fill="#ffd166" /><circle cx={-154} cy={-454} r={7} fill="#6bdc8b" />
      {children}
    </g>
    <path d="M-300 0H300L338 34Q340 46 326 46H-326Q-340 46 -338 34Z" fill="#c9d2e6" />
    <rect x={-60} y={4} width={120} height={10} rx={5} fill="#a9b5d3" />
    {mac && <Fruta x={0} y={30} />}
  </g>
);

const Pantalla: React.FC<{s: number; txt: string; ords: number[][]; ts: number[]; oro?: number; ap?: number; dd?: number}> = ({s, txt, ords, ts, oro = 0, ap = -1, dd = 0.6}) => (
  <>
    <rect x={-206} y={-428} width={412} height={40} rx={20} fill="#fff" stroke="#9fb4e8" strokeWidth={3} />
    <text x={-186} y={-401} fontSize={22} fill={INK} fontWeight={700}>{txt}{Math.floor(s * 2.5) % 2 === 0 ? '|' : ''}</text>
    <Lista s={s} cx={0} y0={-336} dy={92} w={404} hh={84} data={H4} ords={ords} ts={ts} oro={oro} ap={ap} dd={dd} />
  </>
);

const Persona: React.FC<{x: number; y: number; k?: number; s: number; fase?: number; traje: string; piel: string; pelo?: string; flip?: boolean; paso?: number; gorra?: boolean; children?: React.ReactNode}> = ({
  x, y, k = 1, s, fase = 0, traje, piel, pelo = '#2a1b14', flip = false, paso = 1, gorra = false, children,
}) => {
  const sw = Math.sin(s * 9 + fase) * 30 * paso;
  const bob = Math.abs(Math.sin(s * 9 + fase)) * 7 * paso + Math.sin(s * 2 + fase) * 2;
  return (
    <g transform={`translate(${x} ${y}) scale(${flip ? -k : k} ${k})`}>
      <ellipse cy={6} rx={64} ry={13} fill="rgba(0,0,0,.28)" />
      <path d={`M-20 -125L${-20 + sw} -12M20 -125L${20 - sw} -12`} stroke="#1c2650" strokeWidth={30} strokeLinecap="round" />
      <ellipse cx={-20 + sw + 6} cy={-6} rx={26} ry={11} fill="#0d1226" />
      <ellipse cx={20 - sw + 6} cy={-6} rx={26} ry={11} fill="#0d1226" />
      <g transform={`translate(0 ${-bob})`}>
        <path d={`M-42 -225L${-72 - sw * 0.5} -125M42 -225L${72 + sw * 0.5} -125`} stroke={traje} strokeWidth={26} strokeLinecap="round" />
        <circle cx={-72 - sw * 0.5} cy={-118} r={15} fill={piel} />
        <circle cx={72 + sw * 0.5} cy={-118} r={15} fill={piel} />
        <rect x={-48} y={-262} width={96} height={152} rx={40} fill={traje} />
        <rect x={-48} y={-262} width={96} height={60} rx={30} fill="rgba(255,255,255,.14)" />
        <circle cy={-308} r={46} fill={piel} />
        {gorra ? <path d="M-48 -318Q0 -382 48 -318L68 -310L-48 -304Z" fill="#101a40" /> : <path d="M-47 -312Q0 -374 47 -312Q20 -338 -47 -312Z" fill={pelo} />}
        {[-17, 17].map((ex) => (
          <g key={ex}><circle cx={ex} cy={-306} r={9} fill="#1a2340" /><circle cx={ex + 3} cy={-309} r={3} fill="#fff" /></g>
        ))}
        <path d="M-12 -286Q0 -276 12 -286" stroke="#7a3b2a" strokeWidth={4} fill="none" strokeLinecap="round" />
        {children}
      </g>
    </g>
  );
};

const Fondo: React.FC = () => {
  const {s} = useS();
  const c = tono(s, [0, A[3], A[5], A[6], A[7], A[8]], ['#0f2150', '#33270c', '#451519', '#13234a', '#0e4030', '#0f2150']);
  return (
    <>
      <Textura tipo="fibra" base={`radial-gradient(ellipse at 50% 40%,${c},#04060d)`} linea="rgba(255,255,255,.07)" luz="rgba(255,255,255,.06)" semilla={625} />
      <svg width={1080} height={1920} style={{position: 'absolute', filter: 'blur(26px)', opacity: 0.5}}>
        <g transform={`translate(${Math.sin(s * 0.3) * 16} 0)`}>
          <rect x={90} y={250} width={300} height={380} fill="#ffd98a" opacity={0.5} />
          <rect x={500} y={430} width={470} height={200} rx={30} fill="#8fa8e8" />
          <rect x={520} y={380} width={430} height={80} rx={30} fill="#e8eefc" />
          <circle cx={960} cy={360} r={60} fill={GOLD} />
        </g>
      </svg>
    </>
  );
};

/* ---------- E1: dos laptops, la misma búsqueda, listas barajadas ---------- */
const E1: React.FC = () => {
  const {s} = useS();
  const sl = 0.92 + 0.08 * q(s, 0, 0.75, eo);
  const bob = Math.sin(s * 3.2) * 7;
  const oL = [[0, 1, 2, 3], [3, 1, 0, 2], [3, 2, 1, 0]], tL = [0, 0.62, 1.25];
  const oR = [[0, 1, 2, 3], [1, 0, 3, 2], [2, 0, 1, 3]], tR = [0, 0.95, 1.75];
  return (
    <Camara paradas={[P(A[0], 540, 900, 0.95), P(A[1], 540, 860, 1.14)]}>
      <Brillo x={270} y={740} r={300} color="rgba(255,200,61,.55)" t0={1.2} />
      <svg width={1080} height={1920}>
        <Laptop id="e1a" x={270 - (1 - sl) * 420} y={LY + bob} k={0.78} mac rot={(1 - sl) * -8}>
          <Pantalla s={s} txt="hoteles en Miami" ords={oL} ts={tL} oro={q(s, 1.3, 2.0)} />
        </Laptop>
        <Laptop id="e1b" x={810 + (1 - sl) * 420} y={LY - bob} k={0.78} rot={(1 - sl) * 8}>
          <Pantalla s={s} txt="hoteles en Miami" ords={oR} ts={tR} />
        </Laptop>
      </svg>
    </Camara>
  );
};

/* ---------- E2: dos manos buscan lo mismo; las listas salen distintas ---------- */
const LY = 1000;
const wy = (k: number) => LY + (-336 + 92 * k) * 0.78;
const Teclado: React.FC<{s: number; x: number; y: number}> = ({s, x, y}) => (
  <g transform={`translate(${x} ${y})`}>
    <rect x={-215} y={-8} width={430} height={110} rx={16} fill="#25335f" stroke="#6f86c4" strokeWidth={4} />
    {Array.from({length: 30}).map((_, i) => {
      const r = Math.floor(i / 10), c = i % 10;
      const f = Math.floor(s * 13);
      const hit = f % 30 === i || (f * 7 + 3) % 30 === i;
      return <rect key={i} x={-195 + c * 39} y={8 + r * 30} width={32} height={24} rx={6} fill={hit ? GOLD : '#41527f'} />;
    })}
  </g>
);
const Mano: React.FC<{s: number; x: number; y: number; skin: string; manga: string; fase: number}> = ({s, x, y, skin, manga, fase}) => (
  <g transform={`translate(${x} ${y})`}>
    <rect x={-60} y={40} width={120} height={220} rx={40} fill={manga} />
    <rect x={-62} y={-40} width={124} height={100} rx={36} fill={skin} />
    {[0, 1, 2, 3].map((j) => {
      const b = Math.max(0, Math.sin(s * 17 + fase + j * 1.9));
      return <rect key={j} x={-58 + j * 31.5} y={-104 + b * 24} width={24} height={78} rx={12} fill={skin} />;
    })}
    <ellipse cx={-70} cy={4} rx={16} ry={32} transform="rotate(24 -70 4)" fill={skin} />
  </g>
);
const E2: React.FC = () => {
  const {s} = useS();
  const tp = en('página'), tn = en('no'), tc = en('ciudad'), tm = en('misma');
  const query = 'Miami · 1 noche';
  const n = Math.floor(q(s, A[1] + 0.3, tc, lineal) * query.length);
  const oL = [[0, 1, 2, 3], [3, 2, 1, 0]], tL = [0, tn];
  const oR = [[0, 1, 2, 3]];
  return (
    <>
      <Camara paradas={[P(A[1], 300, 950, 1.45), P(en('hotel') + 0.2, 300, 990, 1.6), P(tp + 0.4, 300, 950, 1.5), P(en('noche'), 780, 950, 1.5), P(tc, 790, 990, 1.65), P(tn - 0.1, 540, 900, 1.05), P(A[2] - 0.3, 540, 900, 1.12)]}>
        <svg width={1080} height={1920}>
          <Teclado s={s} x={270} y={LY + 112} />
          <Teclado s={s} x={810} y={LY + 112} />
          <Laptop id="e2a" x={270} y={LY} k={0.78} mac>
            <Pantalla s={s} txt={query.slice(0, n)} ords={oL} ts={tL} oro={q(s, tn + 0.3, tn + 1.0)} ap={tp} />
          </Laptop>
          <Laptop id="e2b" x={810} y={LY} k={0.78}>
            <Pantalla s={s} txt={query.slice(0, n)} ords={oR} ts={[0]} ap={tp} />
          </Laptop>
          <Mano s={s} x={270} y={LY + 180} skin="#8a5636" manga="#2d3f78" fase={0} />
          <Mano s={s} x={810} y={LY + 180} skin="#f2c9a0" manga="#7a3b52" fase={1.3} />
          {[0, 1, 2, 3].map((c) => {
            const r = q(s, tn + 0.25 + c * 0.08, tn + 0.8 + c * 0.08, eo);
            if (r <= 0) return null;
            const y1 = wy(3 - c), y2 = wy(c);
            const col = c >= 2 ? GOLD : '#ffffff';
            return (
              <g key={c}>
                <path d={`M443 ${y1}C520 ${y1} 560 ${y2} 637 ${y2}`} fill="none" stroke={col} strokeWidth={7} strokeLinecap="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - r} />
                {r > 0.95 && <polygon points={`637,${y2} 616,${y2 - 14} 616,${y2 + 14}`} fill={col} />}
              </g>
            );
          })}
        </svg>
      </Camara>
      <Chip texto="MISMA BÚSQUEDA" x={540} y={470} t0={tm} t1={tn - 0.2} color={GOLD} size={58} />
      <Chip texto="≠ LISTA" x={540} y={470} t0={en('lista')- 0.4} color={RED} size={64} />
    </>
  );
};

/* ---------- E3: el periódico y la lupa dorada ---------- */
const E3: React.FC = () => {
  const {s, spr} = useS();
  const u = q(s, 9.5, 10.5, eo);
  const tW = en('Wall'), tJ = en('Journal'), tO = en('Orbitz');
  const hl = q(s, tW - 0.1, tJ + 0.4);
  const lx = interpolate(s, [11.4, 12.0, 13.0, 14.3, 14.75], [700, 300, -158, -158, 0], {...clamp, easing: ei});
  const ly = interpolate(s, [11.4, 12.0, 13.0, 14.3, 14.75], [-60, -150, -300, -300, 150], {...clamp, easing: ei});
  const ls = 0.4 + 0.6 * spr(11.4, 12, 160);
  const pl = q(s, 13.4, 14.8, lineal);
  const pulso = 1 + 0.06 * Math.sin(s * 9) * q(s, 13.45, 13.9);
  return (
    <>
      <Camara paradas={[P(9.4, 540, 800, 1.65), P(12.2, 480, 800, 1.8), P(13.1, 420, 860, 1.6), P(14.35, 540, 1230, 1.0), P(14.9, 540, 1230, 1.0)]}>
        <svg width={1080} height={1920}>
          <g transform={`translate(540 1080) rotate(${(1 - u) * -10}) scale(${Math.max(0.02, u)} 1)`}>
            <rect x={-380} y={-490} width={760} height={980} fill="#f4ecd8" stroke="#cbbd9a" strokeWidth={6} />
            {[-190, 0, 190].map((fx) => <rect key={fx} x={fx - 3} y={-490} width={6} height={980} fill="rgba(0,0,0,.18)" opacity={1 - u + 0.35} />)}
            <rect x={-330} y={-452} width={660 * hl} height={62} fill={GOLD} opacity={0.6} />
            <text y={-410} textAnchor="middle" fontFamily="Georgia, serif" fontSize={44} fontWeight={800} fill="#222">THE WALL STREET JOURNAL</text>
            <path d="M-340 -382H340M-340 -374H340" stroke="#222" strokeWidth={3} />
            <text y={-350} textAnchor="middle" fontFamily="Georgia, serif" fontSize={22} fill="#555">JUNIO DE 2012</text>
            <text x={-340} y={-290} fontFamily="Georgia, serif" fontSize={46} fontWeight={800} fill="#222">ON ORBITZ, MAC USERS</text>
            <text x={-340} y={-232} fontFamily="Georgia, serif" fontSize={42} fontWeight={800} fill="#222">STEERED TO PRICIER HOTELS</text>
            {Array.from({length: 7}).map((_, i) => <rect key={'a' + i} x={-340} y={-190 + i * 26} width={i % 3 === 2 ? 240 : 310} height={12} rx={6} fill="#b9ad8d" />)}
            {Array.from({length: 7}).map((_, i) => <rect key={'b' + i} x={30} y={-190 + i * 26} width={i % 3 === 1 ? 250 : 310} height={12} rx={6} fill="#b9ad8d" />)}
            <g transform={`translate(0 150) scale(${pulso})`}>
              <rect x={-170} y={-115} width={340} height={230} rx={16} fill="#1b2748" stroke={GOLD} strokeWidth={q(s, 13.45, 13.9) * 8 + 4} />
              <rect x={-152} y={-97} width={304} height={194} rx={8} fill="#f1f5ff" />
              {[0, 1, 2].map((i) => <rect key={i} x={-136} y={-78 + i * 54} width={272} height={42} rx={10} fill={i === 0 ? GOLD : '#b8c8ee'} />)}
            </g>
            {Array.from({length: 6}).map((_, i) => <rect key={'c' + i} x={-340} y={310 + i * 26} width={i % 2 ? 560 : 680} height={12} rx={6} fill="#b9ad8d" />)}
            {pl > 0 && pl < 1 && (
              <g>
                <path d={`M-420 330Q0 150 ${-420 + 840 * pl} ${330 - Math.sin(pl * Math.PI) * 180}`} fill="none" stroke="#4c8dff" strokeWidth={6} strokeDasharray="4 16" strokeLinecap="round" opacity={0.8} />
                <g transform={`translate(${-420 + 840 * pl} ${330 - Math.sin(pl * Math.PI) * 180 - 20}) rotate(${-30 + 60 * pl})`}>
                  <path d="M-34 0L40 -12L-6 8L-10 30L-20 10Z" fill="#4c8dff" stroke="#fff" strokeWidth={4} strokeLinejoin="round" />
                </g>
              </g>
            )}
            {s > 11.3 && (
              <g transform={`translate(${lx} ${ly + Math.sin(s * 5) * 4}) scale(${ls})`}>
                <defs><clipPath id="e3lupa"><circle r={105} /></clipPath></defs>
                <rect x={60} y={72} width={150} height={34} rx={17} transform="rotate(45)" fill="#b9780f" />
                <circle r={108} fill="#fff7da" />
                <g clipPath="url(#e3lupa)">
                  <rect x={-110} y={-110} width={220} height={220} fill="#fff7da" />
                  <rect x={-100} y={-30 + 0} width={200 * q(s, tO, tO + 0.3)} height={56} fill={GOLD} />
                  <text textAnchor="middle" y={14} fontFamily="Georgia, serif" fontSize={44} fontWeight={800} fill="#222">ORBITZ</text>
                </g>
                <circle r={108} fill="none" stroke={GOLD} strokeWidth={20} />
                <circle r={96} fill="none" stroke="rgba(255,255,255,.55)" strokeWidth={4} />
              </g>
            )}
          </g>
        </svg>
      </Camara>
      <Chip texto="2012" x={540} y={470} t0={en('doce')} t1={11.9} color={GOLD} size={84} />
    </>
  );
};

/* ---------- E4: dentro de la pantalla, el portero y la alfombra dorada ---------- */
const Tag: React.FC<{x: number; y: number; mac: boolean; glow: number}> = ({x, y, mac, glow}) => (
  <g transform={`translate(${x} ${y}) scale(${1 + glow * 0.12})`}>
    <rect x={-62} y={-24} width={124} height={48} rx={16} fill={mac ? GOLD : '#8d99b5'} stroke={mac ? '#fff3b0' : '#c9d2e6'} strokeWidth={4} />
    {mac && <g transform="translate(-34 0) scale(.7)"><Fruta x={0} y={0} /></g>}
    <text x={mac ? 14 : 0} y={10} textAnchor="middle" fontSize={30} fontWeight={800} fill={INK}>{mac ? 'MAC' : 'PC'}</text>
    <path d="M-10 24L0 38L10 24Z" fill={mac ? GOLD : '#8d99b5'} />
  </g>
);
const E4: React.FC = () => {
  const {s, spr} = useS();
  const sh = s - A[3];
  const tMac = en('Mac');
  const pcX = (j: number) => ((j * 290 + sh * 85) % 1140) - 260;
  const maX = (j: number) => ((j * 430 + sh * 110) % 1460) - 260;
