/* ---------- montaje: pasos entre sitios atados a su palabra ---------- */
export const Escena: React.FC = () => {
  const {s} = useS();
  const p1 = en('dos', 2), p2 = en('página', 3), p3 = en('Hoy');
  let body: React.ReactNode;
  if (s < p1 - 0.5) body = s < A[1] ? <E1 /> : <E2 />;
  else if (s < p2 - 0.5) body = <Paso t={p1} tipo="alejar" x={540} y={1000} antes={<E2 />} despues={<E3 />} />;
  else if (s < p2 + 0.4) body = <Paso t={p2} tipo="entrar" x={540} y={1000} antes={<E3 />} despues={<E4 />} />;
  else if (s < A[4]) body = <E4 />;
  else if (s < A[5]) body = <E5 />;
  else if (s < p3 - 0.25) body = <E6 />;
  else if (s < p3 + 0.2) body = <Paso t={p3} tipo="barrido" antes={<E6 />} despues={<E7 />} />;
  else if (s < A[7]) body = <E7 />;
  else if (s < A[8]) body = <E8 />;
  else body = <E9 />;
  return (
    <AbsoluteFill>
      <Fondo />
      <AbsoluteFill style={{fontFamily: FONT}}>{body}</AbsoluteFill>
      <Profundidad color="rgba(4,6,16,.34)" lejos="rgba(255,255,255,.08)" manchas={3} deriva={0.6} semilla={625} />
    </AbsoluteFill>
  );
};

